struct vec2_t {
    float x;
    float y;

    vec2_t operator-(const vec2_t &rhs) const;
    float *vec2_sub(float *dst, float *rhs);
};

static __inline float player_update_vector_angle(const vec2_t &v)
{
    return (float)atan2(v.y, v.x);
}

vec2_t shot_offset = *(const vec2_t *)player_position
    - *(const vec2_t *)&random_offset;
float shot_heading =
    player_update_vector_angle(shot_offset) - 1.5707964f;
